```sql
START TRANSACTION;

SET @PendingStatusId = 10;
SET @CancelledStatusId = 40;

UPDATE `Order`
SET 
    OrderStatusId = @CancelledStatusId,
    UpdatedOnUtc = UTC_TIMESTAMP()
WHERE 
    OrderStatusId = @PendingStatusId
    AND CreatedOnUtc <= UTC_TIMESTAMP() - INTERVAL 30 DAY;

COMMIT;
```
